"""standoff_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +y from 5 extrusion(s) and 6 cut(s), applied in order;
each is an outline in the xz plane between two levels. Units: mm.
Run:  python standoff_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = 0.0    # level along y
z1 = 6.0    # level along y
z2 = 12.0    # level along y
z3 = 15.0    # level along y
z4 = 18.0    # level along y
hole_d1 = 6.0
hole_d2 = 11.0

DIR = (0, 1, 0)


def P(a, b):
    """Point (x, z) in the sketch plane (y = 0)."""
    return (a, 0, b)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: y 0.0 to 12.0 ------------------------------
outline_1 = cf.wire(
    Edge.makeCircle(8.0, P(-37.25, 21.5), DIR),
)
part = prism(outline_1, z0, z2)

# ---- 2. extrusion: y 0.0 to 12.0 ------------------------------
outline_2 = cf.wire(
    Edge.makeCircle(8.0, P(37.25, 21.5), DIR),
)
part = part + prism(outline_2, z0, z2)

# ---- 3. extrusion: y 0.0 to 12.0 ------------------------------
outline_3 = cf.wire(
    Edge.makeCircle(8.0, P(0.0, -43.0), DIR),
)
part = part + prism(outline_3, z0, z2)

# ---- 4. extrusion: y 12.0 to 15.0 ------------------------------
outline_4 = cf.wire(
    Edge.makeThreePointArc(P(-22.3612, 33.1617), P(0.0, 40.0), P(22.3612, 33.1617)),
    Edge.makeThreePointArc(P(22.3612, 33.1617), P(27.1731, 31.4802), P(32.1775, 32.3814)),
    Edge.makeThreePointArc(P(32.1775, 32.3814), P(47.0767, 28.3874), P(44.1394, 11.6814)),
    Edge.makeThreePointArc(P(44.1394, 11.6814), P(40.8483, 7.7929), P(39.9032, 2.7999)),
    Edge.makeThreePointArc(P(39.9032, 2.7999), P(35.6692, -18.1027), P(17.5199, -35.9597)),
    Edge.makeThreePointArc(P(17.5199, -35.9597), P(13.6705, -39.2688), P(11.9461, -44.0637)),
    Edge.makeThreePointArc(P(11.9461, -44.0637), P(0.0, -55.0), P(-11.9461, -44.0637)),
    Edge.makeThreePointArc(P(-11.9461, -44.0637), P(-13.6705, -39.2688), P(-17.5199, -35.9597)),
    Edge.makeThreePointArc(P(-17.5199, -35.9597), P(-35.6692, -18.1027), P(-39.9032, 2.7999)),
    Edge.makeThreePointArc(P(-39.9032, 2.7999), P(-40.8483, 7.7929), P(-44.1394, 11.6814)),
    Edge.makeThreePointArc(P(-44.1394, 11.6814), P(-47.0767, 28.3874), P(-32.1775, 32.3814)),
    Edge.makeThreePointArc(P(-32.1775, 32.3814), P(-27.1731, 31.4802), P(-22.3612, 33.1617)),
)
part = part + prism(outline_4, z2, z3)

# ---- 5. extrusion: y 15.0 to 18.0 ------------------------------
outline_5 = cf.wire(
    Edge.makeThreePointArc(P(-14.9342, -44.3298), P(0.0, -58.0), P(14.9342, -44.3298)),
    Edge.makeThreePointArc(P(14.9342, -44.3298), P(16.1419, -40.9695), P(18.8338, -38.6566)),
    Edge.makeThreePointArc(P(18.8338, -38.6566), P(36.0254, -23.477), P(42.8959, 3.0099)),
    Edge.makeThreePointArc(P(42.8959, 3.0099), P(43.5569, 6.503), P(45.8625, 9.2256)),
    Edge.makeThreePointArc(P(45.8625, 9.2256), P(50.8422, 27.8444), P(30.91, 35.1004)),
    Edge.makeThreePointArc(P(30.91, 35.1004), P(27.4103, 34.4708), P(24.0384, 35.6491)),
    Edge.makeThreePointArc(P(24.0384, 35.6491), P(0.0, 43.0), P(-24.0384, 35.6491)),
    Edge.makeThreePointArc(P(-24.0384, 35.6491), P(-27.4103, 34.4708), P(-30.91, 35.1004)),
    Edge.makeThreePointArc(P(-30.91, 35.1004), P(-50.8422, 27.8444), P(-45.8625, 9.2256)),
    Edge.makeThreePointArc(P(-45.8625, 9.2256), P(-43.5569, 6.503), P(-42.8959, 3.0099)),
    Edge.makeThreePointArc(P(-42.8959, 3.0099), P(-36.0254, -23.477), P(-18.8338, -38.6566)),
    Edge.makeThreePointArc(P(-18.8338, -38.6566), P(-16.1419, -40.9695), P(-14.9342, -44.3298)),
)
part = part + prism(outline_5, z3, z4)

# ---- round holes: (x, z, diameter, from, to) ------------------------
for a, b, d, lo, hi in [
    (-37.25, 21.5, hole_d1, z0, z1),
    (37.25, 21.5, hole_d1, z0, z1),
    (0.0, -43.0, hole_d1, z0, z1),
    (-37.25, 21.5, hole_d2, z1, z4),
    (37.25, 21.5, hole_d2, z1, z4),
    (0.0, -43.0, hole_d2, z1, z4),
]:
    part = part - hole(a, b, d, lo, hi)

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "standoff_exact.step")
